import { describe, test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { validateIssuanceContract } from "../src/issuance-contract.ts";

const here = dirname(fileURLToPath(import.meta.url));
const contractPath = resolve(here, "../../../specs/issuance.v0.json");
const REQUIRED_EVENT_GROUPS = [
  "run_lifecycle",
  "runtime_identity",
  "user_instruction",
  "tool_call",
  "evidence_claim",
  "approval_safety",
  "actor_attribution"
];

const frozen = () => JSON.parse(readFileSync(contractPath, "utf8"));

const passingEntry = () => {
  const contract = frozen();
  return {
    evidence: {
      metric_observations: Object.keys(contract.metric_factor_map).map((metric_id) => ({
        metric_id,
        state: "SCORED",
        opportunity_id: `${metric_id}-opportunity`
      })),
      safety: { verdict_state: "SAFE" },
      evidence_coverage: { n: 8, d: 10 },
      adapter_core_events: [...REQUIRED_EVENT_GROUPS],
      trace_integrity: {
        artifact_digest_verified: true,
        revision_digest_verified: true,
        evidence_digest_verified: true
      },
      invalidators: []
    },
    expected: { issuable: true, failed_gates: [] }
  };
};

const documentWith = (entry) => ({
  ...frozen(),
  canonical_candidates: { nested: entry }
});

const declareOnlyFailure = (entry, gateId) => {
  entry.expected = { issuable: false, failed_gates: [gateId] };
};

const expectMalformed = (label, mutate, componentHints) => {
  const entry = passingEntry();
  mutate(entry);

  const result = validateIssuanceContract(documentWith(entry));
  assert.equal(result.ok, false, `accepted malformed candidate: ${label}`);
  assert.ok(result.errors.length > 0, `${label} returned no validation error`);

  const details = result.errors.join("\n").toLowerCase();
  assert.ok(details.includes("nested"), `${label} did not identify candidate nested: ${result.errors.join("; ")}`);
  assert.ok(
    componentHints.some((hint) => details.includes(hint.toLowerCase())),
    `${label} did not identify the malformed component: ${result.errors.join("; ")}`
  );
};

describe("issuance contract nested candidate validation", () => {
  test("continues to accept well-formed passing and failed-gate candidates", () => {
    const passing = validateIssuanceContract(documentWith(passingEntry()));
    assert.equal(passing.ok, true, passing.errors.join("; "));

    const unsafe = passingEntry();
    unsafe.evidence.safety.verdict_state = "S2";
    declareOnlyFailure(unsafe, "REQUIRED_SAFETY");
    const unsafeResult = validateIssuanceContract(documentWith(unsafe));
    assert.equal(unsafeResult.ok, true, unsafeResult.errors.join("; "));
  });

  test("rejects malformed nested candidate declarations instead of accepting matching failed-gate fixtures", () => {
    const cases = [
      ["undeclared candidate-entry field", (entry) => { entry.undeclared_candidate_property = true; }, ["undeclared_candidate_property"]],
      ["undeclared expected-verdict field", (entry) => { entry.expected.undeclared_expected_property = true; }, ["undeclared_expected_property"]],
      ["missing expected issuable", (entry) => { delete entry.expected.issuable; }, ["expected", "issuable"]],
      ["non-boolean expected issuable", (entry) => { entry.expected.issuable = "true"; }, ["expected", "issuable"]],
      ["non-string expected failed gate", (entry) => { entry.expected.failed_gates = [7]; }, ["expected", "failed_gates"]],
      ["undeclared safety field", (entry) => { entry.evidence.safety.undeclared_safety_property = true; }, ["undeclared_safety_property"]],
      ["unrecognised safety state", (entry) => {
        entry.evidence.safety.verdict_state = "UNKNOWN_SAFETY_STATE";
        declareOnlyFailure(entry, "REQUIRED_SAFETY");
      }, ["safety", "verdict"]],
      ["non-object safety", (entry) => {
        entry.evidence.safety = [];
        declareOnlyFailure(entry, "REQUIRED_SAFETY");
      }, ["safety"]],
      ["non-array adapter events", (entry) => {
        entry.evidence.adapter_core_events = {};
        declareOnlyFailure(entry, "ADAPTER_CORE_EVENTS");
      }, ["adapter_core_events", "event"]],
      ["non-string adapter event", (entry) => { entry.evidence.adapter_core_events.push(7); }, ["adapter_core_events", "event"]],
      ["missing trace-integrity key", (entry) => {
        delete entry.evidence.trace_integrity.evidence_digest_verified;
        declareOnlyFailure(entry, "TRACE_INTEGRITY");
      }, ["trace_integrity", "integrity"]],
      ["undeclared trace-integrity field", (entry) => { entry.evidence.trace_integrity.undeclared_integrity_property = true; }, ["undeclared_integrity_property"]],
      ["non-boolean trace-integrity value", (entry) => {
        entry.evidence.trace_integrity.artifact_digest_verified = "true";
        declareOnlyFailure(entry, "TRACE_INTEGRITY");
      }, ["trace_integrity", "integrity"]],
      ["non-array invalidators", (entry) => { entry.evidence.invalidators = {}; }, ["invalidators", "invalidator"]],
      ["non-string invalidator", (entry) => {
        entry.evidence.invalidators = [7];
        declareOnlyFailure(entry, "NO_INVALIDATOR");
      }, ["invalidators", "invalidator"]]
    ];

    for (const [label, mutate, componentHints] of cases) {
      expectMalformed(label, mutate, componentHints);
    }
  });
});
